mapper.select:
/*LGVATT00011.retrieveOSEmpIdCard*/ SELECT car.employee_no AS employee_no ,em.full_name_local AS employee_name ,em.org_name_local AS emp_org_name ,car.id_card_no AS id_card_no ,to_char(car.effective_start_date, 'DD/MM/YYYY') AS effective_start_date ,to_char(car.effective_end_date, 'DD/MM/YYYY') AS effective_end_date ,to_char(car.creation_date, 'DD/MM/YYYY') AS creation_date ,car.vendor_code AS vendor_code FROM tb_att_emp_idcard_m car ,emp_master em WHERE em.employee_number = car.employee_no AND em.grade IN (SELECT lcc.common_code FROM lgcom_common_code_c lcc WHERE lcc.code_type_code = 'LGVHR_ATT_OS_EMP_GRADE' AND lcc.use_flag = 'Y')
AND em.employee_number = #{employeeNo}
AND em.full_name_local = #{employeeName}
AND em.organization_id = #{orgName}
AND car.effective_start_date BETWEEN to_date(#{fromDate}, 'DD/MM/YYYY') AND nvl(to_date(#{toDate}, 'DD/MM/YYYY'), trunc(sysdate))
ORDER BY car.employee_no

mapper.insert:
/*LGVATT00011.excelDownData*/ INSERT INTO xxlge_export_info (SESSION_ID, CREATED_BY, CREATION_DATE, SEQ_NO, CHARACTER_SET_NAME , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8) SELECT AI.* FROM (SELECT #{sessionId} ,#{USER_SESSION.applicationUserId} ,SYSDATE ,1 ,'KO16KSC5601' ,'Employee No' AS employee_no ,'Employee Name' AS employee_name ,'Organization' AS emp_org_name ,'ID Card No' AS id_card_no ,'Effective Start Date' AS effective_start_date ,'Effective End Date' AS effective_end_date ,'Vendor Code' AS vendor_code ,'Vendor Name' AS vendor_name FROM DUAL UNION ALL SELECT #{sessionId} ,#{USER_SESSION.applicationUserId} ,sysdate ,2 ,'KO16KSC5601' ,car.employee_no AS employee_no ,em.full_name_local AS employee_name ,em.org_name_local AS emp_org_name ,to_char(car.id_card_no) AS id_card_no ,to_char(car.effective_start_date, 'DD/MM/YYYY') AS effective_start_date ,to_char(car.effective_end_date, 'DD/MM/YYYY') AS effective_end_date ,car.vendor_code AS vendor_code ,(SELECT vm.vendor_name FROM tb_vendor_master vm WHERE vm.vendor_code = car.vendor_code AND ROWNUM = 1) AS vendor_name FROM tb_att_emp_idcard_m car ,emp_master em WHERE em.employee_number = car.employee_no AND em.grade IN (SELECT lcc.common_code FROM lgcom_common_code_c lcc WHERE lcc.code_type_code = 'LGVHR_ATT_OS_EMP_GRADE' AND lcc.use_flag = 'Y')
AND em.employee_number = #{employeeNo}
AND em.full_name_local = #{employeeName}
AND em.organization_id = #{orgName}
AND car.effective_start_date BETWEEN to_date(#{fromDate}, 'DD/MM/YYYY') AND nvl(to_date(#{toDate}, 'DD/MM/YYYY'), trunc(sysdate))
ORDER BY employee_no ) AI
